const codeIndexStaleAfter = 48 * time.Hour // = one missed fire of the 24h code-index-refresh cadence

func codeIndexFreshness(ctx context.Context, db *sql.DB) string {
	var sha string
	var updatedAt time.Time
	err := db.QueryRowContext(ctx,
		`SELECT COALESCE(commit_sha,''), updated_at FROM code_symbols\n\t\t ORDER BY updated_at DESC LIMIT 1`).Scan(&sha, &updatedAt)
	if err == sql.ErrNoRows {
		return freshnessBanner("", time.Time{}, time.Now(), codeIndexStaleAfter, nil)
	}
	return freshnessBanner(sha, updatedAt, time.Now(), codeIndexStaleAfter, err)
}

func freshnessBanner(sha string, updatedAt, now time.Time, staleAfter time.Duration, queryErr error) string {
	if queryErr != nil { return fmt.Sprintf("(index freshness UNKNOWN — %v; treat every empty answer below as unknown, not absent)\n", queryErr) }
	if updatedAt.IsZero() { return "!! CODE INDEX EMPTY — … Every answer below is UNKNOWN, not absent. Run index-orchestrator … !!\n" }
	age := now.Sub(updatedAt)
	if age > staleAfter {
		return fmt.Sprintf("!! CODE INDEX STALE: last refreshed %s ago (%s) at commit %s — code newer than that is NOT in the index, so a 'no matches' answer below may mean NOT YET INDEXED, not absent. Run index-orchestrator to refresh. !!\n", formatAge(age), updatedAt.Format("2006-01-02"), shortSHA(sha))
	}
	return fmt.Sprintf("(index freshness: refreshed %s ago at commit %s)\n", formatAge(age), shortSHA(sha))
}

func TestFreshnessBanner(t *testing.T) {
	now := time.Date(2026, 7, 24, 12, 0, 0, 0, time.UTC)
	t.Run("stale index: loud, names age, date, sha and the remedy", func(t *testing.T) {
		got := freshnessBanner("e3176f8abc", now.Add(-20*24*time.Hour), now, 48*time.Hour, nil)
		for _, must := range []string{"STALE", "20d", "e3176f8", "NOT YET INDEXED", "index-orchestrator"} {
			if !strings.Contains(got, must) { t.Fatalf("stale banner must contain %q: %q", must, got) }
		}
	})
	// + fresh-quiet, boundary, empty, query-error subtests (see file)
}
